<template>
  <div class="qr-code">
    <div class="item-box qcode-box">
      <div class="title">
        <span class="left main-color-font">提货时，向团长出示二维码提货</span>
      </div>
      <div class="img-box">
        <div class="qcode"><img :src="myInfo.code_img" alt=""></div>
        <div class="desc main-color-font">您也可以</div>
        <div class="btn"><button class="main-color-font main-color-border" @click="openMask">使用提货码</button></div>
      </div>
    </div>

    <div class="qcode-mask" v-show="showQcodeMask" @click="closeMask">
      <div class="content" @click.stop="prventClick">
        <div class="title">您的提货码</div>
        <div class="num-list">
          <div class="item" v-for="(item, index) in myInfo.code" :key="index">{{item}}</div>
        </div>
        <div class="tip">当日有效</div>
        <div class="close" @click="closeMask">×</div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'QrCode',
  data () {
    return {
      showQcodeMask: false,
      myInfo: ''
    }
  },
  created () {
    this.getMyInfo()
  },
  destroyed () {
    this.showQcodeMask = false
  },
  methods: {
    openMask () {
      this.showQcodeMask = true
    },
    closeMask () {
      this.showQcodeMask = false
    },
    prventClick () {
      return false
    },
    async getMyInfo () {
      let res = await this.$api.getMyInfo({ leader_id: this.$util.storage.get('leader_id') })
      if (!res) return
      res.code = res.code.split('')
      this.myInfo = res
    }
  }
}
</script>

<style lang="stylus" scoped>
.qr-code
  position relative
  background #fff
  flexbox()
  align-items center
  justify-content center
  .qcode-box
    background #fff
    border-radius 6px
    padding 0 10px
    color #333
    text-align center
    .title
      font-size 16px
      color $color-main
      margin-bottom 40px
    .img-box
      .qcode
        width 200px
        height 200px
        margin 0 auto
        img
          width 100%
          height 100%
      .desc
        color $color-main
        font-size 14px
        margin 25px 0 10px
      .btn
        button
          color $color-main
          border 1PX solid $color-main
          background #fff
          padding 10px 60px
          border-radius 25px
          font-size 14px
          &:active
            opacity 0.6
  .qcode-mask
    position absolute
    top 0
    left 0
    bottom 0
    right 0
    background rgba(0, 0, 0, .65)
    flexbox()
    align-items center
    .content
      margin 0 25px
      width 100%
      border-radius 6px
      background #fff
      text-align center
      position relative
      .title
        font-size 16px
        padding 20px 0
      .num-list
        padding 20px 0
        flexbox()
        justify-content center
        .item
          font-size 24px
          font-weight 500
          padding 14px 8px
          border-radius 4px
          box-shadow 0 2px 5px #e5e5e5
          border 1PX solid #efefef
          margin-right 5px
          &:last-child
            margin-right 0
      .tip
        padding 20px 0
        color #999
      .close
        position absolute
        right 0
        top 0
        padding 10px
        color #bbb
        font-size 24px
</style>
